export default async function read({ tenantId, clientId, clientSecret, siteId, listId }, context) {
  for (const v of [tenantId, clientId, clientSecret, siteId, listId])
    if (typeof v !== "string" || !v.trim() || v.startsWith("YOUR_"))
      throw Error("Configure Microsoft application, site and list");
  if (!/^[a-zA-Z0-9.-]+$/.test(tenantId)) throw Error("Invalid tenant ID");
  let tokenResponse;
  try {
    tokenResponse = await context.fetch(
      `https://login.microsoftonline.com/${encodeURIComponent(tenantId)}/oauth2/v2.0/token`,
      {
        method: "POST",
        headers: { "content-type": "application/x-www-form-urlencoded" },
        body:
          "client_id=" +
          encodeURIComponent(clientId) +
          "&client_secret=" +
          encodeURIComponent(clientSecret) +
          "&scope=" +
          encodeURIComponent("https://graph.microsoft.com/.default") +
          "&grant_type=client_credentials",
      },
    );
  } catch {
    throw Error("Microsoft token request failed");
  }
  if (!tokenResponse.ok) throw Error("Microsoft token request rejected");
  const token = (await tokenResponse.json()).access_token;
  if (typeof token !== "string" || !token) throw Error("Microsoft token missing");
  let url = `https://graph.microsoft.com/v1.0/sites/${encodeURIComponent(siteId)}/lists/${encodeURIComponent(listId)}/items?%24expand=fields`,
    items = [],
    seen = new Set();
  while (url) {
    if (!url.startsWith("https://graph.microsoft.com/v1.0/") || seen.has(url))
      throw Error("Invalid Graph next link");
    seen.add(url);
    if (seen.size > 1000) throw Error("Graph page limit exceeded");
    let r;
    try {
      r = await context.fetch(url, {
        headers: { authorization: "Bearer " + token, accept: "application/json" },
      });
    } catch {
      throw Error("Graph list request failed");
    }
    if (!r.ok) throw Error("Graph list request rejected");
    const page = await r.json();
    if (!Array.isArray(page?.value)) throw Error("Invalid Graph list page");
    items.push(...page.value);
    url = page["@odata.nextLink"] ?? null;
    if (url !== null && typeof url !== "string") throw Error("Invalid Graph next link");
  }
  return { items };
}
